import Collections from "./Collections.js"

const { onDrage, contentArea } = Drage({ hor: "right" })

// Parameters
const PARAMS = {
	Collection: "Petroleum",
	Feed: 0.02011,
	Kill: 0.04994,
	DeltaT: 1.5,
	Iterations: 5,
	Scale: 2,
	Radius: 0.02,
	Wrap: true,
	Render: {
		Palette: {
